//! `ub` generated by `mlirformat tblgen` (`ub.gen.rs`) against the `mlir-opt` 22.1.8 fixtures.
//! One test crate per dialect so cargo builds them in parallel; `cargo test --features gen-tests`.

#[path = "../common/mod.rs"]
mod common;
#[path = "ub.gen.rs"]
mod ub;

#[test]
fn ub_matches_mlir_opt() {
    let mut opt = mlirformat::MlirOpt::new();
    opt.load(ub::UbDialect);
    common::Fixtures::check_dialect(&opt, "ub");
}
